package rowsmith;

/**
 * Where the value of a column of a planned row comes from: the test ({@code set(...)}), the
 * {@link RowsmithSetup} value pattern, the referenced parent row, the database (identity, sequence,
 * generated column, DEFAULT), NULL left as is, or generated by Rowsmith from the row number.
 */
public enum ValueSource {
    USER, SETUP, PARENT_ROW, DATABASE_GENERATED, DATABASE_DEFAULT, LEFT_NULL, ROWSMITH
}
